  const [groupeType, setGroupeType] = useState('alphabet');
  const [showGenerateForm, setShowGenerateForm] = useState(false);
  const [loading, setLoading] = useState(true);

  const currentYear = 2025; // Année actuelle fixée à 2025

  // Mémoïsation des étudiants triés
  const etudiantsTries = useMemo(() => {
    return [...etudiants].sort((a, b) => {
      if (a.idGroupe && b.idGroupe) return a.idGroupe - b.idGroupe;
      if (a.idGroupe) return -1;
      if (b.idGroupe) return 1;
      return 0;
    });
  }, [etudiants]);

  useEffect(() => {
    fetchData();
  }, []);

  const fetchData = async () => {
    try {
      const [etudiantsResponse, groupesResponse] = await Promise.all([
        axios.get('http://localhost:5000/api/etudiants'),
        axios.get('http://localhost:5000/api/groupes')
      ]);

      const groupesMap = new Map(groupesResponse.data.map(g => [g.idGroupe, g.nomGroupe]));
      const etudiantsAvecGroupes = etudiantsResponse.data.map(etudiant => ({
        ...etudiant,
        nomGroupe: groupesMap.get(etudiant.idGroupe) || "-",
        // Assure que l'année est un nombre
        annee: Number(etudiant.annee) || currentYear
      }));

      setEtudiants(etudiantsAvecGroupes);
      setGroupes(groupesResponse.data);
    } catch (err) {
      console.error("Erreur lors de la récupération des données :", err);
    } finally {
      setLoading(false);
    }
  };

